// ── 暴露到全域（供 avatarSvg 和 sprite-manager 使用）
window.SPRITES = {
  FLOWER_FRAMES,
  MONKEY_FRAMES,
  NING_FRAMES,
};

// ── 待機動畫播放 8 FPS
// 從 TRIP_CONFIG.members 讀取，不寫死角色清單
(function startSpriteAnim() {
  var ANIM_FPS = 8;
  var frame = 0;
  setInterval(function() {
    var members = (window.TRIP_CONFIG && window.TRIP_CONFIG.members) || [];
    members.forEach(function(m) {
      var frames = window.SPRITES && window.SPRITES[m.spriteKey];
      if (!frames || frames.length <= 1) return;
      // 場景裡的角色 SVG（id 由 scene.js 建立）
      var sceneId = 'svg' + m.name;
      var el = document.getElementById(sceneId);
      if (el) el.innerHTML = frames[frame % frames.length];
    });
    frame++;
  }, 1000 / ANIM_FPS);
})();